    const host=this.element.querySelector('.ui-preview-host');this.view=renderWidgetTree(host,structuredClone(d),{preview:!this.testing,fileUrl,select:(node,event)=>{this.selected=node.id;this.doc.view.widgetSelection=node.id;this.beginMove(event,false);}});
